using System;
using System.Collections.Generic;

class Program
{
    // Describe a C# type definition string with precise keywords.
    // Input is a simplified type declaration string. Output format: sorted comma-separated keywords.
    // Rules:
    // - Contains "class" -> "reference-type"
    // - Contains "struct" -> "value-type"
    // - Contains "interface" -> "contract"
    // - Contains "sealed" -> "non-inheritable"
    // - Contains "abstract" -> "must-inherit"
    // - Contains "static" -> "singleton-like"
    // - Contains "IDisposable" -> "disposable"
    // - Contains "IEnumerable" or "IEnumerator" -> "iterable"
    // - Contains "async" or "Task" -> "async-capable"
    // - Contains generic <T> pattern -> "generic"
    // - Contains "where T :" -> "constrained-generic"
    static string DescribeType(string typeDecl)
    {

golden_completion:
var keywords = new SortedSet<string>();
if (typeDecl.Contains("class")) keywords.Add("reference-type");
if (typeDecl.Contains("struct")) keywords.Add("value-type");
if (typeDecl.Contains("interface")) keywords.Add("contract");
if (typeDecl.Contains("sealed")) keywords.Add("non-inheritable");
if (typeDecl.Contains("abstract")) keywords.Add("must-inherit");
if (typeDecl.Contains("static")) keywords.Add("singleton-like");
if (typeDecl.Contains("IDisposable")) keywords.Add("disposable");
if (typeDecl.Contains("IEnumerable") || typeDecl.Contains("IEnumerator")) keywords.Add("iterable");
if (typeDecl.Contains("async") || typeDecl.Contains("Task")) keywords.Add("async-capable");
if (typeDecl.Contains("<") && typeDecl.Contains(">")) keywords.Add("generic");
if (typeDecl.Contains("where") && typeDecl.Contains(":")) keywords.Add("constrained-generic");
return string.Join(", ", keywords);

suffix:
    }

    static void Main()
    {
        string t1 = "public sealed class MyService : IDisposable";
        string d1 = DescribeType(t1);
        if (!d1.Contains("non-inheritable")) throw new Exception($"Sealed: {d1}");
        if (!d1.Contains("disposable")) throw new Exception($"Disposable: {d1}");
        if (!d1.Contains("reference-type")) throw new Exception($"Class: {d1}");

        string t2 = "public abstract class Repository<T> where T : class";
        string d2 = DescribeType(t2);
        if (!d2.Contains("must-inherit")) throw new Exception($"Abstract: {d2}");
        if (!d2.Contains("generic")) throw new Exception($"Generic: {d2}");
        if (!d2.Contains("constrained-generic")) throw new Exception($"Constrained: {d2}");

        Console.WriteLine("Visible checks passed.");
    }
}

